  ensureAccount('ACC-540001','540001','إعلانات وتسويق','expense','ACC-5400',2,true);
  ensureAccount('ACC-540002','540002','شحن وتوصيل','expense','ACC-5400',2,true);
  const fin=ensureAccount('ACC-5500','5500','مصاريف مالية','expense','ACC-5000',1,false);fin.isLeaf=false;
  ensureAccount('ACC-550001','550001','عمولات ومصاريف بنكية','expense','ACC-5500',2,true);
