  const parentIds=new Set(d.accounts.map(x=>x.parentId).filter(Boolean));
  for(const a of d.accounts){if(a.type==='expense'){a.normalSide='debit';if(parentIds.has(a.id))a.isLeaf=false;else if(a.isLeaf==null)a.isLeaf=true}}
  // Analytical trees.
  if(!d.costCenters.length)d.costCenters.push({id:'CC-ROOT',code:'CC',name:'مراكز التكلفة',parentId:'',isLeaf:false,active:true,system:true,createdAt:A.now()});
  let ccRoot=d.costCenters.find(x=>x.id==='CC-ROOT');if(!ccRoot){ccRoot={id:'CC-ROOT',code:'CC',name:'مراكز التكلفة',parentId:'',isLeaf:false,active:true,system:true,createdAt:A.now()};d.costCenters.unshift(ccRoot)}else ccRoot.isLeaf=false;
  for(const c of d.costCenters.filter(x=>x.id!=='CC-ROOT')){if(c.isLeaf==null)c.isLeaf=!d.costCenters.some(k=>k.parentId===c.id);if(!c.parentId)c.parentId='CC-ROOT'}
  for(const b of d.branches||[]){const id='CC-BR-'+b.id;let c=d.costCenters.find(x=>x.id===id);if(!c)d.costCenters.push({id,code:`CC-${b.code||b.id}`.toUpperCase(),name:`${b.name}`,parentId:'CC-ROOT',branchId:b.id,isLeaf:true,active:b.active!==false,system:true,createdAt:A.now()})}
  d.settings.defaultCostCenterId=d.settings.defaultCostCenterId&&d.costCenters.some(x=>x.id===d.settings.defaultCostCenterId&&x.isLeaf!==false)?d.settings.defaultCostCenterId:(d.costCenters.find(x=>x.isLeaf!==false&&x.active!==false)?.id||'');
  if(!d.projects.length)d.projects.push({id:'PRJ-ROOT',code:'PRJ',name:'المشاريع والعقود',parentId:'',isLeaf:false,active:true,system:true,createdAt:A.now()});
