ensureDB();A.saveDB(true);
A.isPostableAccount=id=>{const a=account(id);return !!a&&a.active!==false&&a.isLeaf!==false&&!D().accounts.some(x=>x.parentId===id)};

function nextChildCode(parent,collection){
  const base=String(parent.code||'').replace(/\s+/g,'');const kids=collection.filter(x=>x.parentId===parent.id);let max=0;
  for(const k of kids){const tail=String(k.code||'').slice(base.length);if(/^\d+$/.test(tail))max=Math.max(max,Number(tail))}
  return base+String(max+1).padStart(2,'0');
}
function treeRows(collection,rootId,getBalance=()=>null){
  const rows=[];const walk=(pid,depth=0)=>collection.filter(x=>x.parentId===pid).sort((a,b)=>String(a.code).localeCompare(String(b.code),undefined,{numeric:true})).forEach(x=>{rows.push({x,depth,balance:getBalance(x)});walk(x.id,depth+1)});walk(rootId,0);return rows;
}

// ---------- Party ledger + vouchers +/- ----------
function inferredVoucherEffect(v){
  if(Number(v.partyEffect)===1||Number(v.partyEffect)===-1)return Number(v.partyEffect);
  if(v.partyType==='customer')return v.direction==='receipt'?-1:1;
  if(v.partyType==='supplier')return v.direction==='payment'?-1:1;
  return 0;
}
function voucherJournalLines(v){
  const amount=round(v.amount),cash=v.accountId||'ACC-1110',effect=inferredVoucherEffect(v),meta={branchId:v.branchId||activeBranch()};
  if(v.partyType==='customer')return effect>0?[{accountId:'ACC-1200',debit:amount,credit:0,...meta},{accountId:cash,debit:0,credit:amount,...meta}]:[{accountId:cash,debit:amount,credit:0,...meta},{accountId:'ACC-1200',debit:0,credit:amount,...meta}];
  if(v.partyType==='supplier')return effect>0?[{accountId:cash,debit:amount,credit:0,...meta},{accountId:'ACC-2100',debit:0,credit:amount,...meta}]:[{accountId:'ACC-2100',debit:amount,credit:0,...meta},{accountId:cash,debit:0,credit:amount,...meta}];
  return v.direction==='receipt'?[{accountId:cash,debit:amount,credit:0,...meta},{accountId:'ACC-4100',debit:0,credit:amount,...meta}]:[{accountId:'ACC-520001',debit:amount,credit:0,costCenterId:D().settings.defaultCostCenterId||'',...meta},{accountId:cash,debit:0,credit:amount,...meta}];
}
function applyVoucher(v,mult=1){
  const p=party(v.partyType,v.partyId),effect=inferredVoucherEffect(v);if(p&&effect)p.balance=round(num(p.balance)+mult*effect*num(v.amount));
  const lines=voucherJournalLines(v).map(l=>mult===1?l:{...l,debit:l.credit,credit:l.debit});
  A.postJournal(`${mult===1?'':'عكس '}${v.direction==='receipt'?'سند قبض':'سند صرف'} ${v.number}`,v.number,lines,v.date||A.today(),true);
}
