function deleteVoucher750(id){const d=D(),v=d.vouchers.find(x=>x.id===id);if(!v)return;if(!A.has('delete'))return A.toast('لا تملك صلاحية الحذف.','error');A.confirmDialog('حذف السند',`${v.number} — سيتم عكس أثر رصيد الطرف والحساب.`,()=>A.atomicMutation(()=>{applyVoucher(v,-1);d.vouchers=d.vouchers.filter(x=>x.id!==id);A.audit('حذف سند','السندات',v.number);A.saveDB();syncNow();A.toast('تم حذف السند وعكس أثره');A.renderCurrent()}))}
function partyLedgerEntries(type,id){
  const d=D(),p=party(type,id),out=[];if(!p)return out;
  if(type==='customer')for(const s of d.sales.filter(x=>x.customerId===id)){const returned=s.status==='returned'||s.returnedAt;out.push({date:s.date||String(s.createdAt||'').slice(0,10),sort:s.createdAt||s.date,doc:s.number,type:'فاتورة بيع',desc:'إجمالي الفاتورة',plus:num(s.total),minus:0});if(num(s.paid))out.push({date:s.date,sort:(s.createdAt||'')+'1',doc:s.number,type:'دفعة فاتورة',desc:'المدفوع داخل الفاتورة',plus:0,minus:num(s.paid)});if(returned){out.push({date:String(s.returnedAt||s.date).slice(0,10),sort:(s.returnedAt||'')+'2',doc:s.number,type:'مرتجع بيع',desc:'عكس الفاتورة',plus:0,minus:num(s.total)});if(num(s.paid))out.push({date:String(s.returnedAt||s.date).slice(0,10),sort:(s.returnedAt||'')+'3',doc:s.number,type:'عكس دفعة',desc:'عكس المدفوع',plus:num(s.paid),minus:0})}}
  if(type==='supplier')for(const x of d.purchases.filter(x=>x.supplierId===id)){const cancelled=x.status==='cancelled';out.push({date:x.date,sort:x.createdAt||x.date,doc:x.number,type:'فاتورة شراء',desc:'إجمالي الفاتورة',plus:num(x.total),minus:0});if(num(x.paid))out.push({date:x.date,sort:(x.createdAt||'')+'1',doc:x.number,type:'دفعة فاتورة',desc:'مدفوع للمورد',plus:0,minus:num(x.paid)});if(cancelled){out.push({date:x.date,sort:(x.updatedAt||x.date)+'2',doc:x.number,type:'إلغاء شراء',desc:'عكس الفاتورة',plus:0,minus:num(x.total)});if(num(x.paid))out.push({date:x.date,sort:(x.updatedAt||x.date)+'3',doc:x.number,type:'عكس دفعة',desc:'عكس المدفوع',plus:num(x.paid),minus:0})}}
  for(const v of d.vouchers.filter(x=>x.partyType===type&&x.partyId===id)){const e=inferredVoucherEffect(v),amt=num(v.amount);out.push({date:v.date,sort:v.createdAt||v.date,doc:v.number,type:v.direction==='receipt'?'سند قبض':'سند صرف',desc:v.notes||v.reference||'',plus:e>0?amt:0,minus:e<0?amt:0})}
  out.sort((a,b)=>String(a.sort||a.date).localeCompare(String(b.sort||b.date)));
  const calc=round(out.reduce((n,x)=>n+num(x.plus)-num(x.minus),0)),diff=round(num(p.balance)-calc);if(Math.abs(diff)>.009)out.unshift({date:p.createdAt?String(p.createdAt).slice(0,10):'',sort:'',doc:'OPEN',type:'رصيد افتتاحي / تسوية',desc:'رصيد سابق مثبت على حساب الطرف',plus:diff>0?diff:0,minus:diff<0?Math.abs(diff):0});
  let balance=0;for(const x of out){balance=round(balance+num(x.plus)-num(x.minus));x.balance=balance}return out;
}
function showPartyLedger(type,id){const p=party(type,id);if(!p)return;const rows=partyLedgerEntries(type,id);A.openModal({title:`سجل ${type==='customer'?'العميل':'المورد'} — ${p.name}`,size:'modal-xl',hideSubmit:true,body:`<div class="party-ledger-summary"><div><small>الرصيد الحالي</small><strong>${A.money(p.balance)}</strong></div><div><small>عدد الحركات</small><strong>${rows.length}</strong></div></div><div class="party-ledger-export"><button class="btn btn-secondary" data-action="party-ledger-excel" data-type="${type}" data-id="${id}">${I('excel')} Excel</button><button class="btn btn-secondary" data-action="party-ledger-pdf" data-type="${type}" data-id="${id}">${I('pdf')} PDF</button></div>${A.table(['التاريخ','المستند','نوع الحركة','البيان','سحب +','سداد −','الرصيد'],rows.map(x=>`<tr><td>${A.dateFmt(x.date)}</td><td><b>${esc(x.doc)}</b></td><td>${esc(x.type)}</td><td>${esc(x.desc||'—')}</td><td>${num(x.plus)?A.money(x.plus):'—'}</td><td>${num(x.minus)?A.money(x.minus):'—'}</td><td><b>${A.money(x.balance)}</b></td></tr>`),A.emptyState('file','لا توجد حركة',''))}`})}
