  const d=D(),isCust=type==='customers',bm=branchManager(),bid=bm?activeBranch():(item?.branchId||activeBranch());A.openModal({title:`${item?'تعديل':'إضافة'} ${isCust?'عميل':'مورد'}`,body:`<div class="form-grid"><label class="field"><span>الاسم</span><input name="name" value="${esc(item?.name||'')}" required></label><label class="field"><span>الهاتف</span><input name="phone" value="${esc(item?.phone||'')}"></label><label class="field"><span>العنوان</span><input name="address" value="${esc(item?.address||'')}"></label><label class="field"><span>الفرع</span>${bm?`<input value="${esc(branchName(bid))}" readonly><input type="hidden" name="branchId" value="${bid}">`:`<select name="branchId">${A.options(d.branches.filter(x=>x.active!==false),'id','name',bid)}</select>`}</label>${item?'':`<label class="field"><span>رصيد افتتاحي</span><input name="openingBalance" type="number" step="0.01" value="0"></label>`}<label class="field"><span>الحالة</span><select name="active"><option value="1" ${item?.active!==false?'selected':''}>نشط</option><option value="0" ${item?.active===false?'selected':''}>موقوف</option></select></label></div>`,onSubmit:fd=>A.atomicMutation(()=>{const opening=item?0:round(fd.get('openingBalance')),target=item||{id:A.uid(isCust?'CUS':'SUP'),createdAt:A.now(),balance:0};Object.assign(target,{name:String(fd.get('name')).trim(),phone:String(fd.get('phone')||'').trim(),address:String(fd.get('address')||'').trim(),branchId:fd.get('branchId')||activeBranch(),active:fd.get('active')==='1',updatedAt:A.now()});if(!item){target.balance=opening;d[type].push(target);if(Math.abs(opening)>.009){const ref=`OPEN-${target.id}`,lines=isCust?(opening>0?[{accountId:'ACC-1200',debit:opening,credit:0,branchId:target.branchId},{accountId:'ACC-3200',debit:0,credit:opening,branchId:target.branchId}]:[{accountId:'ACC-3200',debit:Math.abs(opening),credit:0,branchId:target.branchId},{accountId:'ACC-1200',debit:0,credit:Math.abs(opening),branchId:target.branchId}]):(opening>0?[{accountId:'ACC-3200',debit:opening,credit:0,branchId:target.branchId},{accountId:'ACC-2100',debit:0,credit:opening,branchId:target.branchId}]:[{accountId:'ACC-2100',debit:Math.abs(opening),credit:0,branchId:target.branchId},{accountId:'ACC-3200',debit:0,credit:Math.abs(opening),branchId:target.branchId}]);A.postJournal(`رصيد افتتاحي ${target.name}`,ref,lines,A.today(),true)}}A.audit(item?'تعديل طرف':'إضافة طرف',title,target.name);A.saveDB();syncNow();A.toast('تم الحفظ');A.renderCurrent()} )})
