// ---------- Expense hierarchy + analytical trees ----------
function expenseAccounts(){return D().accounts.filter(a=>a.type==='expense'&&a.active!==false)}
function expenseLeafs(){const d=D(),parents=new Set(d.accounts.map(a=>a.parentId));return expenseAccounts().filter(a=>a.isLeaf!==false&&!parents.has(a.id))}
function revenueLeafs(){const d=D(),parents=new Set(d.accounts.map(a=>a.parentId));return d.accounts.filter(a=>a.type==='revenue'&&a.active!==false&&a.isLeaf!==false&&!parents.has(a.id))}
function openExpenseAccount(item=null){const d=D(),parents=expenseAccounts().filter(x=>x.id!==item?.id),parent=account(item?.parentId)||account('ACC-5200')||account('ACC-5000');A.openModal({title:item?'تعديل حساب مصروف':'إضافة حساب/مجموعة مصروف',body:`<div class="form-grid"><label class="field"><span>الحساب الأب</span><select name="parentId" id="expParent">${A.options(parents,'id','name',parent?.id)}</select></label><label class="field"><span>النوع</span><select name="kind"><option value="detail" ${item?.isLeaf!==false?'selected':''}>حساب حركة نهائي</option><option value="group" ${item?.isLeaf===false?'selected':''}>مجموعة تجميعية</option></select></label><label class="field"><span>الكود</span><input name="code" id="expCode" value="${esc(item?.code||nextChildCode(parent||{code:'5',id:''},d.accounts))}" readonly></label><label class="field"><span>اسم الحساب</span><input name="name" value="${esc(item?.name||'')}" required></label><label class="field"><span>الطبيعة</span><input value="مدين دائماً" readonly></label><label class="field"><span>الحالة</span><select name="active"><option value="1" ${item?.active!==false?'selected':''}>نشط</option><option value="0" ${item?.active===false?'selected':''}>موقوف</option></select></label></div>`,onSubmit:fd=>{const pid=fd.get('parentId'),par=account(pid);if(!par||par.type!=='expense')throw Error('اختر حساب مصروف أباً صحيحاً.');const code=item?.code||nextChildCode(par,d.accounts);if(d.accounts.some(a=>a.id!==item?.id&&a.code===code))throw Error('الكود مستخدم.');const target=item||{id:A.uid('ACC'),createdAt:A.now()};Object.assign(target,{code,name:String(fd.get('name')).trim(),type:'expense',parentId:pid,level:num(par.level)+1,isLeaf:fd.get('kind')==='detail',normalSide:'debit',active:fd.get('active')==='1',updatedAt:A.now()});par.isLeaf=false;if(!item)d.accounts.push(target);A.audit(item?'تعديل حساب مصروف':'إضافة حساب مصروف','المصاريف',`${code} ${target.name}`);A.saveDB();A.toast('تم حفظ حساب المصروف');A.renderCurrent()},afterOpen:form=>{$('#expParent',form).onchange=e=>{const par=account(e.target.value);$('#expCode',form).value=item?.code||nextChildCode(par,D().accounts)}}})}
function openAnalytical(kind,item=null){const d=D(),arr=kind==='cost'?d.costCenters:d.projects,rootId=kind==='cost'?'CC-ROOT':'PRJ-ROOT',label=kind==='cost'?'مركز تكلفة':'مشروع / عقد',root=arr.find(x=>x.id===rootId);const parent=arr.find(x=>x.id===item?.parentId)||root;A.openModal({title:`${item?'تعديل':'إضافة'} ${label}`,body:`<div class="form-grid"><label class="field"><span>الأب</span><select name="parentId" id="anaParent">${A.options(arr.filter(x=>x.id!==item?.id),'id','name',parent?.id)}</select></label><label class="field"><span>النوع</span><select name="kind"><option value="detail" ${item?.isLeaf!==false?'selected':''}>فرع تحليلي نهائي</option><option value="group" ${item?.isLeaf===false?'selected':''}>مجموعة</option></select></label><label class="field"><span>الكود</span><input name="code" id="anaCode" value="${esc(item?.code||nextChildCode(parent||{code:kind==='cost'?'CC':'PRJ',id:''},arr))}" readonly></label><label class="field"><span>الاسم</span><input name="name" value="${esc(item?.name||'')}" required></label><label class="field"><span>الحالة</span><select name="active"><option value="1" ${item?.active!==false?'selected':''}>نشط</option><option value="0" ${item?.active===false?'selected':''}>موقوف</option></select></label></div>`,onSubmit:fd=>{const par=arr.find(x=>x.id===fd.get('parentId'));if(!par)throw Error('اختر الأب.');const target=item||{id:A.uid(kind==='cost'?'CC':'PRJ'),createdAt:A.now()};Object.assign(target,{parentId:par.id,code:item?.code||nextChildCode(par,arr),name:String(fd.get('name')).trim(),isLeaf:fd.get('kind')==='detail',active:fd.get('active')==='1',updatedAt:A.now()});par.isLeaf=false;if(!item)arr.push(target);A.audit(item?'تعديل شجرة تحليلية':'إضافة شجرة تحليلية',kind==='cost'?'مراكز التكلفة':'المشاريع',target.name);A.saveDB();A.renderCurrent()},afterOpen:form=>{$('#anaParent',form).onchange=e=>{const par=arr.find(x=>x.id===e.target.value);$('#anaCode',form).value=item?.code||nextChildCode(par,arr)}}})}
function financeLines(x,reverse=false){const amount=num(x.amount),cash=x.accountId||'ACC-1110',ledger=x.ledgerAccountId||(x.type==='expense'?'ACC-5200':'ACC-4100'),meta={costCenterId:x.costCenterId||'',projectId:x.projectId||'',branchId:x.branchId||activeBranch()};let lines=x.type==='expense'?[{accountId:ledger,debit:amount,credit:0,...meta},{accountId:cash,debit:0,credit:amount,branchId:meta.branchId}]:[{accountId:cash,debit:amount,credit:0,branchId:meta.branchId},{accountId:ledger,debit:0,credit:amount,...meta}];if(reverse)lines=lines.map(l=>({...l,debit:l.credit,credit:l.debit}));return lines}
function openFinance750(existing=null){const d=D(),x=existing||{},isExpense=x.type!=='income',ccLeaf=d.costCenters.filter(c=>c.active!==false&&c.isLeaf!==false),projects=d.projects.filter(p=>p.active!==false&&p.isLeaf!==false);A.openModal({title:existing?'تعديل حركة مالية':'مصروف / إيراد',size:'modal-lg',body:`<div class="form-grid cols-3"><label class="field"><span>نوع الحركة</span><select name="type" id="finType"><option value="expense" ${isExpense?'selected':''}>مصروف</option><option value="income" ${!isExpense?'selected':''}>إيراد</option></select></label><label class="field"><span>التاريخ</span><input name="date" type="date" value="${esc(x.date||A.today())}" required></label><label class="field"><span>المبلغ</span><input name="amount" type="number" min="0.01" step="0.01" value="${num(x.amount)||''}" required></label><label class="field"><span>حساب المصروف / الإيراد</span><select name="ledgerAccountId" id="finLedger" class="searchable-select"></select></label><label class="field"><span>حساب الدفع / التحصيل</span><select name="accountId" class="searchable-select">${A.options(A.paymentAccounts(),'id','name',x.accountId||A.paymentAccounts()[0]?.id)}</select></label><label class="field"><span>مركز التكلفة *</span><select name="costCenterId" class="searchable-select" required>${A.options(ccLeaf,'id','name',x.costCenterId||d.settings.defaultCostCenterId)}</select></label><label class="field"><span>المشروع / العقد</span><select name="projectId" class="searchable-select"><option value="">بدون مشروع</option>${A.options(projects,'id','name',x.projectId||'')}</select></label><label class="field"><span>الفرع</span><input value="${esc(branchName(x.branchId||activeBranch()))}" readonly></label><label class="field"><span>المرجع</span><input name="reference" value="${esc(x.reference||'')}"></label><label class="field full"><span>البيان</span><textarea name="notes" required>${esc(x.notes||x.category||'')}</textarea></label></div>`,onSubmit:fd=>A.atomicMutation(()=>{const type=fd.get('type'),amount=round(fd.get('amount')),date=fd.get('date'),ledgerAccountId=fd.get('ledgerAccountId'),costCenterId=fd.get('costCenterId');if(amount<=0)throw Error('اكتب مبلغاً صحيحاً.');if(type==='expense'&&!A.isPostableAccount(ledgerAccountId))throw Error('اختر حساب حركة نهائي للمصروف، وليس حساباً تجميعياً.');if(type==='expense'&&!costCenterId)throw Error('مركز التكلفة إلزامي للمصروف.');A.validateOpenFinancialDate?.(date);if(existing)A.postJournal(`عكس ${existing.type==='expense'?'مصروف':'إيراد'} — ${existing.category||existing.notes}`,existing.reference||existing.id,financeLines(existing,true),existing.date||A.today(),true);const target=existing||{id:A.uid('FIN'),createdAt:A.now()};Object.assign(target,{type,date,amount,ledgerAccountId,category:account(ledgerAccountId)?.name||String(fd.get('notes')).trim(),accountId:fd.get('accountId')||'ACC-1110',costCenterId,projectId:fd.get('projectId')||'',branchId:activeBranch(),reference:fd.get('reference')||'',notes:fd.get('notes')||'',updatedAt:A.now(),userId:A.currentUser()?.id||''});if(!existing)d.finance.unshift(target);A.postJournal(`${type==='expense'?'مصروف':'إيراد'} — ${target.category}`,target.reference||target.id,financeLines(target),date,true);A.audit(existing?'تعديل حركة مالية':'إضافة حركة مالية','الحركات المالية',`${target.category} — ${amount}`);A.saveDB();syncNow();A.toast('تم حفظ الحركة وربطها بالشجرة التحليلية');A.renderCurrent()}),afterOpen:form=>{const t=$('#finType',form),l=$('#finLedger',form);const fill=()=>{const list=t.value==='expense'?expenseLeafs():revenueLeafs();l.innerHTML=A.options(list,'id','name',x.ledgerAccountId||(t.value==='expense'?'ACC-520001':'ACC-4100'));A.enhanceSelects(form)};t.onchange=fill;fill()}})}
function deleteFinance750(id){const d=D(),x=d.finance.find(f=>f.id===id);if(!x)return;if(!A.has('delete'))return A.toast('لا تملك صلاحية الحذف.','error');A.confirmDialog('حذف الحركة','سيتم عكس القيد المحاسبي ثم حذف الحركة.',()=>A.atomicMutation(()=>{A.postJournal(`عكس ${x.type==='expense'?'مصروف':'إيراد'} — ${x.category}`,x.reference||x.id,financeLines(x,true),x.date||A.today(),true);d.finance=d.finance.filter(f=>f.id!==id);A.saveDB();syncNow();A.toast('تم الحذف والعكس');A.renderCurrent()}))}
