  if(tab==='projects'){const rows=treeRows(d.projects,'PRJ-ROOT');body=`<article class="panel"><div class="panel-head"><div><h3>شجرة المشاريع والعقود</h3><small>تحليل مستقل لمصاريف وإيرادات كل مشروع أو عقد.</small></div>${btn('add-project-v750','إضافة مشروع','plus')}</div>${A.table(['الكود','المشروع / العقد','النوع','الحالة','الإجراء'],rows.map(({x,depth})=>`<tr><td>${esc(x.code)}</td><td><div style="padding-inline-start:${depth*20}px"><b>${depth?'↳ ':''}${esc(x.name)}</b></div></td><td>${x.isLeaf===false?'مجموعة':'نهائي'}</td><td>${A.badge(x.active!==false?'نشط':'موقوف',x.active!==false?'green':'red')}</td><td>${x.system?'':ib('edit-project-v750','edit','تعديل',`data-id="${x.id}"`)}</td></tr>`))}</article>`}
  root.innerHTML=`${A.pageHead('المصاريف والتحليل المالي','شجرة مالية مترابطة + مراكز تكلفة + مشاريع',tab==='movements'?btn('add-finance-v750','حركة جديدة','plus'):'')}<div class="v750-tabs">${tabs.map(([id,label])=>`<button class="${tab===id?'active':''}" data-action="expense-tab-v750" data-tab="${id}">${esc(label)}</button>`).join('')}</div>${body}`;
