// ---------- Branch managers ----------
const MANAGER_PERMS=['dashboard','cashier','sales','purchases','inventory','transfers','parties','debts','vouchers','cheques','expenses','employees','branches_view','warehouses_view','customer_groups','price_groups','installments','messaging','discount','price_change','sales_return','sales_credit','warehouse_select'];
function assignBranchManager(branchId,employeeId){const d=D(),b=d.branches.find(x=>x.id===branchId),e=d.employees.find(x=>x.id===employeeId);if(!b||!e)throw Error('اختر الفرع والموظف.');for(const x of d.employees)if(x.branchId===branchId&&x.id!==e.id)x.isBranchManager=false;e.branchId=branchId;e.isBranchManager=true;e.role='مدير فرع';e.permissions=[...new Set(MANAGER_PERMS)];e.authVersion=A.uid('AUTH');e.active=true;b.managerEmployeeId=e.id;b.updatedAt=A.now();}
