function employeesView(root){const d=D(),list=branchManager()?d.employees.filter(e=>!e.system&&e.branchId===activeBranch()):d.employees;root.innerHTML=`${A.pageHead('الموظفون والصلاحيات',branchManager()?'موظفو فرعك فقط':'تعيين موظفين لكل فرع وإصدار ملفات دخول مشفرة',btn('add-employee-v750','إضافة موظف','plus'))}<article class="panel">${A.table(['الموظف','الدور','الفرع','مدير فرع','الصلاحيات','الحالة','ملف الدخول','الإجراءات'],list.map(e=>`<tr><td><b>${esc(e.name)}</b></td><td>${esc(e.role)}</td><td>${esc(branchName(e.branchId))}</td><td>${e.isBranchManager?A.badge('مدير الفرع','primary'):'—'}</td><td>${e.system?'كامل':e.permissions?.length||0}</td><td>${A.badge(e.active!==false?'نشط':'موقوف',e.active!==false?'green':'red')}</td><td>${e.system?'—':`<button class="btn btn-secondary btn-sm" data-action="download-employee-v750" data-id="${e.id}">${I('download')} .mzauth</button>`}</td><td>${e.system?'':ib('edit-employee-v750','edit','تعديل',`data-id="${e.id}"`)}</td></tr>`))}</article>`}
function openEmployee750(item=null){const d=D(),bm=branchManager(),fixedBranch=bm?activeBranch():(item?.branchId||activeBranch()),selected=item?.permissions||['dashboard','cashier','sales'];A.openModal({title:item?'تعديل موظف':'إضافة موظف',size:'modal-lg',body:`<div class="form-grid cols-3"><label class="field"><span>الاسم</span><input name="name" value="${esc(item?.name||'')}" required></label><label class="field"><span>الدور</span><input name="role" value="${esc(item?.role||'موظف')}"></label><label class="field"><span>الفرع</span>${bm?`<input value="${esc(branchName(fixedBranch))}" readonly><input type="hidden" name="branchId" value="${fixedBranch}">`:`<select name="branchId">${A.options(d.branches.filter(b=>b.active!==false),'id','name',fixedBranch)}</select>`}</label>${bm?'':`<label class="check-row"><input name="isBranchManager" type="checkbox" ${item?.isBranchManager?'checked':''}><span>تعيينه مديراً للفرع</span></label>`}<label class="field"><span>الحالة</span><select name="active"><option value="1" ${item?.active!==false?'selected':''}>نشط</option><option value="0" ${item?.active===false?'selected':''}>موقوف</option></select></label></div><section class="form-section"><h4>الصلاحيات</h4><div class="permissions-grid">${A.PERMISSIONS.filter(([id])=>!bm||!['branch_select','branches_manage','warehouses_manage','settings','accounting','reports'].includes(id)).map(([id,label])=>`<label class="permission-item"><input type="checkbox" name="permission" value="${id}" ${selected.includes(id)?'checked':''}><span>${esc(label)}</span></label>`).join('')}</div></section>`,onSubmit:fd=>{let permissions=fd.getAll('permission'),bid=fd.get('branchId')||fixedBranch,isMgr=!bm&&fd.get('isBranchManager')==='on';if(isMgr)permissions=[...MANAGER_PERMS];if(!permissions.length)throw Error('اختر صلاحية واحدة على الأقل.');const target=item||{id:A.uid('EMP'),createdAt:A.now(),username:'',passwordHash:'',system:false};Object.assign(target,{name:String(fd.get('name')).trim(),role:isMgr?'مدير فرع':String(fd.get('role')||'موظف').trim(),branchId:bid,permissions,active:fd.get('active')==='1',isBranchManager:isMgr||(item?.isBranchManager&&bm),authVersion:A.uid('AUTH'),updatedAt:A.now()});if(!item)d.employees.push(target);if(isMgr)assignBranchManager(bid,target.id);A.audit(item?'تعديل موظف':'إضافة موظف','الموظفون',target.name);A.saveDB();syncNow();A.toast('تم الحفظ وإصدار صلاحية ملف دخول جديدة');A.renderCurrent()}})}

